// 0–4: length ≥ 8 is the floor; then a digit, mixed case, and a symbol each add one.
export function passwordScore(pw: string) {
  if (pw.length < 8) return 0;
  let s = 1;
  if (/\d/.test(pw)) s++;
  if (/[a-z]/.test(pw) && /[A-Z]/.test(pw)) s++;
  if (/[^A-Za-z0-9]/.test(pw)) s++;
  return s;
}

// Four segments, ok-green when filled (§1.10).
export function StrengthMeter({ score, caption }: { score: number; caption: string }) {
  const c = useColors();
  return (
    <View style={{ gap: 7 }}>
      <View style={{ flexDirection: 'row', gap: 5 }}>
        {[1, 2, 3, 4].map((i) => (
          <View key={i} style={{ flex: 1, height: 4, borderRadius: 2, backgroundColor: i <= score ? c.ok : c.soft }} />
        ))}
      </View>
      <AppText style={{ fontFamily: fonts.light, fontSize: 11, color: c.muted }}>{caption}</AppText>
    </View>
  );
}
